select year(opened_date) as opened_year, concat_ws(', ', sort_array(collect_set(status))) as status_values, sum(case when account_type = 'SAVINGS' then balance else 0 end) as savings_balance, count(distinct balance) as unique_account_types from accounts where status not in ('CLOSED', 'FROZEN') and account_type not in ('CREDIT', 'LOAN', 'SAVINGS') group by opened_year order by savings_balance;
